--
-- Table structure for table `loans`
--

DROP TABLE IF EXISTS `loans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `loans` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `member_no` varchar(30) DEFAULT NULL,
  `applicant_name` varchar(150) DEFAULT NULL,
  `nip` varchar(30) DEFAULT NULL,
  `unit_kerja` varchar(120) DEFAULT NULL,
  `phone` varchar(30) DEFAULT NULL,
  `amount` decimal(14,2) NOT NULL,
  `term_months` int(10) unsigned NOT NULL,
  `purpose` text NOT NULL,
  `selfie_path` varchar(255) DEFAULT NULL,
  `pdf_path` varchar(255) DEFAULT NULL,
  `transfer_evidence_path` varchar(255) DEFAULT NULL,
  `transfered_at` timestamp NULL DEFAULT NULL,
  `transfered_by` bigint(20) unsigned DEFAULT NULL,
  `pdf_token` varchar(64) DEFAULT NULL,
  `import_loan_code` varchar(100) DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'submitted',
  `sekretaris_id` bigint(20) unsigned DEFAULT NULL,
  `sekretaris_note` text DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `bendahara_id` bigint(20) unsigned DEFAULT NULL,
  `bendahara_note` text DEFAULT NULL,
  `treasurer_approved_at` timestamp NULL DEFAULT NULL,
  `ketua_id` bigint(20) unsigned DEFAULT NULL,
  `ketua_note` text DEFAULT NULL,
  `chairman_approved_at` timestamp NULL DEFAULT NULL,
  `rejected_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `loans_import_loan_code_unique` (`import_loan_code`),
  KEY `loans_user_id_foreign` (`user_id`),
  KEY `loans_sekretaris_id_foreign` (`sekretaris_id`),
  KEY `loans_bendahara_id_foreign` (`bendahara_id`),
  KEY `loans_ketua_id_foreign` (`ketua_id`),
  KEY `loans_status_index` (`status`),
  KEY `loans_pdf_token_index` (`pdf_token`),
  CONSTRAINT `loans_bendahara_id_foreign` FOREIGN KEY (`bendahara_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `loans_ketua_id_foreign` FOREIGN KEY (`ketua_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `loans_sekretaris_id_foreign` FOREIGN KEY (`sekretaris_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `loans_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=379 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

